    "question": "Cho phản ứng CH4(g) + 2O2(g) → CO2(g) + 2H2O(g), biết năng lượng liên kết C-H là 413 kJ/mol, O=O là 495 kJ/mol, C=O (trong CO2) là 799 kJ/mol, O-H là 463 kJ/mol. Biết CH4 có 4 liên kết C-H và CO2 có 2 liên kết đôi C=O, H2O có 2 liên kết O-H mỗi phân tử. Tính ΔrH°298 của phản ứng theo năng lượng liên kết.",
