    "correctAnswer": "Toàn bộ chương trình Hóa học 10 xây dựng một chuỗi logic liên kết chặt chẽ: cấu hình electron (đặc biệt electron lớp ngoài cùng) của nguyên tử quyết định vị trí của nguyên tố trong bảng tuần hoàn (số lớp electron quyết định chu kì, số electron lớp ngoài cùng quyết định nhóm A); từ vị trí trong bảng tuần hoàn, có thể suy ra xu hướng biến đổi độ âm điện, bán kính nguyên tử, tính kim loại - phi kim; các yếu tố này lại quyết định loại liên kết hóa học được hình thành khi nguyên tố đó kết hợp với nguyên tố khác (liên kết ion giữa kim loại điển hình và phi kim điển hình, liên kết cộng hóa trị giữa hai phi kim); cuối cùng, loại liên kết và độ bền của liên kết đó quyết định trực tiếp tính chất hóa học đặc trưng của đơn chất và hợp chất (ví dụ nhóm halogen có 7 electron lớp ngoài cùng nên dễ nhận electron, có tính oxi hóa mạnh giảm dần từ F đến I do bán kính tăng dần, đồng thời hợp chất hydrogen halide của chúng có tính acid tăng dần từ HF đến HI do độ bền liên kết H-X giảm dần) - toàn bộ các tính chất này đều có thể suy luận, giải thích một cách nhất quán, có hệ thống chỉ từ việc nắm vững cấu tạo nguyên tử ban đầu",
